import java.util.*;
import java.io.*;

public class Main {
    static long[] maxSumList(long[] a, long[] b) {
        // Write your solution here
        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); a[i] = (long) in.nval;
        }
        in.nextToken();
        int m = (int) in.nval;
        long[] b = new long[m];
        for (int i = 0; i < m; i++) {
            in.nextToken(); b[i] = (long) in.nval;
        }
        long[] res = maxSumList(a, b);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
